	extra_id INTEGER NOT NULL, 
	quantity INTEGER, 
	unit_price NUMERIC(10, 2) NOT NULL, 
	total_price NUMERIC(10, 2) NOT NULL, 
	CONSTRAINT order_item_extras_pkey PRIMARY KEY (order_item_extra_id), 
	CONSTRAINT order_item_extras_extra_id_fkey FOREIGN KEY(extra_id) REFERENCES menu_extras (extra_id), 
	CONSTRAINT order_item_extras_order_item_id_fkey FOREIGN KEY(order_item_id) REFERENCES order_items (order_item_id) ON DELETE CASCADE
);


