    IF seq_name IS NOT NULL THEN
        EXECUTE 'SELECT COALESCE(MAX("refund_id"), 1) FROM "payment_refunds"' INTO max_val;
        PERFORM setval(seq_name, max_val, true);
    END IF;
END $$;
